//! Fixture-based tests of every converter (fixtures/ingest, generated by fixtures/ingest/gen/*).
//! OCR runs through `StubOcr` everywhere; the real Apple Vision engine is exercised on macOS.
use lowk_ingest::*;
use lowk_types::*;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::sync::Arc;

fn fx(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../fixtures/ingest")
        .join(name)
}

fn req(path: &Path, ocr: bool) -> IngestRequest {
    let ext = path.extension().unwrap().to_string_lossy().to_string();
    IngestRequest {
        doc: Ulid::new(),
        source_path: path.to_string_lossy().into(),
        kind: DocKind::from_extension(&ext).unwrap(),
        languages: vec!["ru".into(), "en".into()],
        ocr,
    }
}

fn run(ing: &Ingestor, path: &Path, ocr: bool) -> Result<IngestedDoc> {
    ing.convert(&req(path, ocr), &mut |_, _| {}, &|| true)
}

fn stub() -> Ingestor {
    Ingestor::with_ocr(Arc::new(StubOcr::new("Распознанный текст recognized text")))
}

fn ok(name: &str) -> IngestedDoc {
    run(&stub(), &fx(name), true).unwrap_or_else(|e| panic!("{name}: {e}"))
}

fn err(name: &str) -> AppError {
    run(&stub(), &fx(name), true).expect_err(name)
}

fn markers(md: &str) -> Vec<u32> {
    md.lines()
        .filter_map(|l| l.strip_prefix("<!-- p:")?.strip_suffix(" -->")?.parse().ok())
        .collect()
}

fn has_warning(d: &IngestedDoc, c: IngestWarningCode) -> bool {
    d.warnings.iter().any(|w| w.code == c)
}

// ------------------------------------------------------------------------------- text-like

#[test]
fn txt_and_md() {
    let t = ok("sample.txt");
    assert_eq!(t.converter, "txt");
    assert_eq!(t.pages, None);
    assert!(t.md.contains("Заметки по проекту") && t.md.contains("квазар-txt"));
    assert!(markers(&t.md).is_empty());

    let m = ok("sample.md");
    assert_eq!(m.converter, "md");
    assert!(m.md.contains("title: Заметка"), "frontmatter is kept: {}", m.md);
    assert!(m.md.contains("# Заголовок") && m.md.contains("quasar-md"));
}

#[test]
fn legacy_cyrillic_encoding() {
    let d = ok("sample-cp1251.txt");
    assert!(d.md.contains("договор поставки"), "{}", d.md);
    assert!(!d.md.contains('\u{FFFD}'));
}

#[test]
fn csv_and_tsv() {
    let c = ok("sample.csv");
    assert_eq!(c.converter, "csv");
    assert_eq!(markers(&c.md), vec![1]);
    assert!(c.md.contains("| Имя | Город | Сумма |"), "{}", c.md);
    assert!(
        c.md.contains("| Пётр \"Лёха\" | Казань | 7 |"),
        "quotes: {}",
        c.md
    );
    assert!(c.md.contains("1 200,50"), "number formatting is kept");
    let t = ok("sample.tsv");
    assert!(t.md.contains("| Anna | Рига |"), "{}", t.md);
}

