#[test]
fn docx_structure() {
    let d = ok("sample.docx");
    assert_eq!(d.converter, "docx");
    assert!(d.md.contains("# Протокол встречи"), "{}", d.md);
    assert!(d.md.contains("# Обзор проекта") && d.md.contains("## Project overview"));
    assert!(
        d.md.contains("- Первый пункт списка\n- Second bullet item"),
        "lists: {}",
        d.md
    );
    assert!(
        d.md.contains("| Задача | Owner | Срок |")
            && d.md.contains("| Подготовить договор | Анна | 2026-11-01 |")
    );
    assert!(
        d.md.contains("[^1]") && d.md.contains("[^1]: Сноска: источник данных"),
        "footnotes: {}",
        d.md
    );
    assert!(d.md.contains("квазар-docx"));
}

#[test]
fn pptx_slides_in_presentation_order_with_notes() {
    let d = ok("sample.pptx");
    assert_eq!(d.converter, "pptx");
    assert_eq!(d.pages, Some(2));
    assert_eq!(markers(&d.md), vec![1, 2]);
    let (p1, p2) = d.md.split_once("<!-- p:2 -->").unwrap();
    assert!(
        p1.contains("## Стратегия запуска") && p1.contains("Цель: выйти на рынок"),
        "{}",
        d.md
    );
    assert!(p1.contains("> Notes: Заметки докладчика"), "notes: {}", d.md);
    assert!(!p1.contains("\n7"), "slide number placeholder is not text");
    assert!(p2.contains("## Roadmap") && p2.contains("квазар-pptx") && p2.contains("| Beta | 2026-12-01 |"));
}

#[test]
fn xlsx_sheets_and_dates() {
    let d = ok("sample.xlsx");
    assert_eq!(d.converter, "xlsx");
    assert_eq!(d.pages, Some(2));
    assert_eq!(markers(&d.md), vec![1, 2]);
    assert!(d.md.contains("## Прайс") && d.md.contains("## Data"));
    assert!(
        d.md.contains("| Яблоки | 120.5 | 2026-11-01 |"),
        "dates keep their format: {}",
        d.md
    );
    assert!(d.md.contains("| Pears | 99 | 2026-11-02 |"));
}

fn xlsx_with_rows(path: &Path, rows: usize) {
    let f = std::fs::File::create(path).unwrap();
    let mut z = zip::ZipWriter::new(f);
    let o = zip::write::SimpleFileOptions::default();
    let w = |z: &mut zip::ZipWriter<std::fs::File>, n: &str, c: &str| {
        z.start_file(n, o).unwrap();
        z.write_all(c.as_bytes()).unwrap();
    };
    w(
        &mut z,
        "[Content_Types].xml",
        r#"<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="xml" ContentType="application/xml"/><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>"#,
    );
    w(
        &mut z,
        "_rels/.rels",
        r#"<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>"#,
    );
    w(
        &mut z,
        "xl/workbook.xml",
        r#"<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Big" sheetId="1" r:id="rId1"/></sheets></workbook>"#,
    );
    w(
        &mut z,
        "xl/_rels/workbook.xml.rels",
        r#"<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>"#,
    );
    let mut sheet = String::from(
        r#"<?xml version="1.0"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>"#,
    );
    sheet.push_str(r#"<row r="1"><c r="A1" t="inlineStr"><is><t>id</t></is></c><c r="B1" t="inlineStr"><is><t>name</t></is></c></row>"#);
    for i in 2..=rows + 1 {
        sheet.push_str(&format!(
            r#"<row r="{i}"><c r="A{i}"><v>{}</v></c><c r="B{i}" t="inlineStr"><is><t>Клиент {}</t></is></c></row>"#,
            i - 1,
            i - 1
        ));
    }
    sheet.push_str("</sheetData></worksheet>");
    w(&mut z, "xl/worksheets/sheet1.xml", &sheet);
    z.finish().unwrap();
}

#[test]
fn big_sheet_5000_rows_is_chunked_with_progress() {
    let dir = tempfile::tempdir().unwrap();
    let p = dir.path().join("big.xlsx");
    xlsx_with_rows(&p, 5000);
    let mut calls = 0;
    let d = stub()
        .convert(&req(&p, true), &mut |_, _| calls += 1, &|| true)
        .unwrap();
    assert!(calls >= 2);
    assert!(
        !has_warning(&d, IngestWarningCode::SheetTruncated),
        "5000 rows fit the default cap"
    );
    assert!(
        d.md.contains("### Big (rows 1-200)") && d.md.contains("### Big (rows 4801-5000)"),
        "chunked"
    );
    assert_eq!(
        d.md.matches("| id | name |").count(),
        25,
        "header repeated per chunk"
    );
    assert!(d.md.contains("| 5000 | Клиент 5000 |"));
    assert_eq!(markers(&d.md), vec![1], "one sheet, one marker");
}

#[test]
fn csv_row_cap_is_reported() {
    let dir = tempfile::tempdir().unwrap();
    let p = dir.path().join("many.csv");
    let mut s = String::from("a,b\n");
    for i in 0..300 {
        s.push_str(&format!("{i},x\n"));
    }
    std::fs::write(&p, s).unwrap();
    let ing = stub().with_limits(Limits {
        max_rows: 100,
        ..Limits::default()
    });
    let d = run(&ing, &p, true).unwrap();
    let w = d
        .warnings
        .iter()
        .find(|w| w.code == IngestWarningCode::SheetTruncated)
        .expect("SheetTruncated");
    assert_eq!(w.page, Some(1));
    assert!(d.md.contains("sheet truncated"));
    assert!(!d.md.contains("| 250 |"));
}

