#[test]
fn pdf_text_layer_with_markers_headings_and_cleanup() {
    let d = ok("text.pdf");
    assert_eq!(d.converter, "pdf-text");
    assert_eq!(d.pages, Some(3));
    assert_eq!(markers(&d.md), vec![1, 2, 3]);
    assert!(d.md.contains("# Договор поставки № 1"), "{}", d.md);
    // punctuation inside Cyrillic runs survives
    assert!(
        d.md.contains("двадцать шестого года. Стоимость партии составляет 1 250 000 рублей, оплата"),
        "{}",
        d.md
    );
    assert!(d
        .md
        .contains("Mixed paragraph: код проекта LOWK-1003 и срок 30 days после подписания."));
    assert!(d.md.contains("квазар-3"));
    // running header and page numbers are gone
    assert!(!d.md.contains("Fixture Corp"), "header removed: {}", d.md);
    assert!(!d.md.contains("Page 1") && !d.md.contains("Page 3"));
    assert!(d.warnings.is_empty());
}

