/// Minimal valid PDF with `n` text pages (Helvetica, Latin text), a repeated header and footer.
fn make_pdf(n: usize) -> Vec<u8> {
    let mut out = b"%PDF-1.4\n".to_vec();
    let mut offs = vec![];
    let mut obj = |out: &mut Vec<u8>, body: String| {
        offs.push(out.len());
        out.extend(format!("{} 0 obj\n{body}\nendobj\n", offs.len()).bytes());
    };
    obj(&mut out, "<< /Type /Catalog /Pages 2 0 R >>".into());
    let kids: Vec<String> = (0..n).map(|i| format!("{} 0 R", 4 + i * 2)).collect();
    obj(
        &mut out,
        format!("<< /Type /Pages /Count {n} /Kids [{}] >>", kids.join(" ")),
    );
    obj(
        &mut out,
        "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>".into(),
    );
    for i in 0..n {
        const W: [&str; 8] = [
            "supplier", "carrier", "invoice", "penalty", "warranty", "tariff", "audit", "escrow",
        ];
        let (a, b, c) = (W[i % 8], W[(i / 8) % 8], W[(i * 3 + 1) % 8]);
        let content = format!(
            "BT /F1 9 Tf 72 800 Td (Annual Report Header) Tj ET\n\
             BT /F1 12 Tf 72 700 Td (Body {i}: the {a} reviews the {b} terms.) Tj 0 -16 Td (Second line about the {c} continues the argument here.) Tj 0 -16 Td (Third line of page {i}, the contract {a} terms.) Tj ET\n\
             BT /F1 9 Tf 72 40 Td (Page {}) Tj ET",
            i + 1
        );
        obj(&mut out, format!("<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Contents {} 0 R /Resources << /Font << /F1 3 0 R >> >> >>", 5 + i * 2));
        obj(
            &mut out,
            format!("<< /Length {} >>\nstream\n{content}\nendstream", content.len()),
        );
    }
    let xref = out.len();
    out.extend(format!("xref\n0 {}\n0000000000 65535 f \n", offs.len() + 1).bytes());
    for o in &offs {
        out.extend(format!("{o:010} 00000 n \n").bytes());
    }
    out.extend(
        format!(
            "trailer\n<< /Size {} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF\n",
            offs.len() + 1
        )
        .bytes(),
    );
    out
}

#[test]
fn pdf_300_pages_with_progress() {
    let dir = tempfile::tempdir().unwrap();
    let p = dir.path().join("long.pdf");
    std::fs::write(&p, make_pdf(300)).unwrap();
    let mut seen = vec![];
    let t0 = std::time::Instant::now();
    let d = stub()
        .convert(
            &req(&p, true),
            &mut |done, total| seen.push((done, total)),
            &|| true,
        )
        .unwrap();
    eprintln!("300 pages in {:?}", t0.elapsed());
    assert_eq!(d.pages, Some(300));
    assert_eq!(markers(&d.md).len(), 300);
    assert_eq!(seen.first(), Some(&(0, 300)));
    assert_eq!(seen.last(), Some(&(300, 300)));
    assert!(seen.windows(2).all(|w| w[0].0 <= w[1].0), "progress is monotonic");
    assert!(
        d.md.contains("Body 299: the"),
        "{}",
        &d.md[d.md.len().saturating_sub(400)..]
    );
    assert!(
        !d.md.contains("Annual Report Header"),
        "running header removed on a long document"
    );
    assert!(!d.md.contains("Page 17\n"), "page numbers removed");
}

