#[test]
fn keynote_is_never_silently_empty() {
    let dir = tempfile::tempdir().unwrap();
    let p = dir.path().join("deck.key");
    std::fs::write(&p, b"PK\x03\x04 not a real keynote").unwrap();
    let e = run(&stub(), &p, true);
    // macOS without Keynote, any other OS: DocUnsupported with the export hint. (A Mac with
    // Keynote installed is exercised by the ignored `keynote_roundtrip_on_a_mac` test.)
    if !Path::new("/Applications/Keynote.app").exists() {
        let e = e.unwrap_err();
        assert_eq!(e.code, ErrorCode::DocUnsupported);
        assert_eq!(e.params.get("export_to").map(String::as_str), Some("pdf|pptx"));
    }
}

#[test]
fn broken_and_encrypted_office() {
    assert_eq!(err("broken.docx").code, ErrorCode::IngestFailed);
    let dir = tempfile::tempdir().unwrap();
    for name in ["x.docx", "x.pptx", "x.xlsx"] {
        let p = dir.path().join(name);
        let mut b = vec![0xD0, 0xCF, 0x11, 0xE0, 0xA1, 0xB1, 0x1A, 0xE1];
        b.extend([0u8; 600]);
        std::fs::write(&p, b).unwrap();
        assert_eq!(
            run(&stub(), &p, true).unwrap_err().code,
            ErrorCode::DocEncrypted,
            "{name}"
        );
    }
}

#[test]
fn size_limits_and_large_file_warning() {
    let big = Ingestor::with_ocr(Arc::new(NoOcr)).with_limits(Limits {
        max_bytes: 100,
        ..Limits::default()
    });
    let e = run(&big, &fx("sample.docx"), true).unwrap_err();
    assert_eq!(e.code, ErrorCode::DocTooLarge);
    let warn = Ingestor::with_ocr(Arc::new(NoOcr)).with_limits(Limits {
        warn_bytes: 100,
        ..Limits::default()
    });
    let d = run(&warn, &fx("sample.docx"), true).unwrap();
    assert!(has_warning(&d, IngestWarningCode::LargeFile));
}

#[test]
fn missing_file_and_cancellation() {
    let e = run(&stub(), &fx("nope.pdf"), true).unwrap_err();
    assert_eq!(e.code, ErrorCode::NotFound);
    // cancel after the first progress report
    let n = std::cell::Cell::new(0);
    let r = stub().convert(
        &req(&fx("sample.pptx"), true),
        &mut |_, _| n.set(n.get() + 1),
        &|| n.get() < 1,
    );
    assert_eq!(r.unwrap_err().code, ErrorCode::IngestCancelled);
    let r = stub().convert(&req(&fx("text.pdf"), true), &mut |_, _| {}, &|| false);
    assert_eq!(r.unwrap_err().code, ErrorCode::IngestCancelled);
}

