// ------------------------------------------------------------------------------- robustness

/// Truncated and bit-flipped copies of every fixture must produce `Ok` or a typed error, never
/// a panic (a panic here would be reported by the converter guard as an `internal` failure).
#[test]
fn corrupted_inputs_never_panic() {
    let dir = tempfile::tempdir().unwrap();
    let mut seed = 0x9E3779B97F4A7C15u64;
    let mut rnd = move || {
        seed ^= seed << 13;
        seed ^= seed >> 7;
        seed ^= seed << 17;
        seed
    };
    let files = [
        "text.pdf",
        "scanned.pdf",
        "sample.docx",
        "sample.pptx",
        "sample.xlsx",
        "sample.csv",
        "sample.md",
        "scan.png",
    ];
    let ing = stub();
    for name in files {
        let bytes = std::fs::read(fx(name)).unwrap();
        let ext = Path::new(name).extension().unwrap().to_string_lossy().to_string();
        for round in 0..12 {
            let mut b = bytes.clone();
            if round % 2 == 0 {
                b.truncate((rnd() as usize % b.len()).max(1));
            } else {
                for _ in 0..(1 + rnd() % 20) {
                    let i = rnd() as usize % b.len();
                    b[i] ^= 1 << (rnd() % 8);
                }
            }
            let p = dir.path().join(format!("c{round}.{ext}"));
            std::fs::write(&p, &b).unwrap();
            if let Err(e) = run(&ing, &p, true) {
                let internal = e.params.get("format").map(String::as_str) == Some("internal");
                assert!(!internal, "{name} round {round}: converter panicked: {e}");
            }
        }
    }
}

